import { useEffect, useRef, useState } from 'react';
import { PageHeader } from '@kerfjs/ui/page-header';
import { StateBanner } from '@kerfjs/ui/state-banner';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import '@kerfjs/ui/layout.css';
type Item = {id: string; title: string};
type Snapshot = {items: Item[] | null; pending: boolean; error: string | null};

export function ListWorkspace({load, onCreate}: {load: (signal: AbortSignal) => Promise<Item[]>; onCreate: () => void}) {
  const [state, setState] = useState<Snapshot>({items:null, pending:true, error:null});
  const [attempt, setAttempt] = useState(0);
  const generation = useRef(0);
  useEffect(() => {
    const request = ++generation.current;
    const controller = new AbortController();
    setState(old => ({...old, pending:true, error:null}));
    load(controller.signal).then(items => {
      if (request === generation.current && !controller.signal.aborted) setState({items, pending:false, error:null});
    }).catch(() => {
      if (request === generation.current && !controller.signal.aborted) setState(old => ({...old, pending:false, error:'Could not load items. Check your connection and try again.'}));
    });
    return () => controller.abort();
  }, [load, attempt]);
  const retry = () => setAttempt(value => value + 1);
  return <section className="kui-layout" aria-label="Items workspace">
    <PageHeader><h1>Items</h1><button onClick={retry} disabled={state.pending}>Refresh</button></PageHeader>
    <p role="status" aria-live="polite">{state.pending ? (state.items === null ? 'Loading items…' : 'Refreshing items. Previous results remain available.') : state.error ? 'Loading failed.' : state.items?.length + ' items loaded.'}</p>
    {state.error && <StateBanner><div role="alert"><strong>Items could not be updated</strong><p>{state.error}</p>{state.items !== null && <p>Showing the last successfully loaded results.</p>}<button onClick={retry}>Try again</button></div></StateBanner>}
    <div aria-busy={state.pending}>
      {state.items === null && state.pending && <div><LoadingSpinner aria-hidden="true"/><p>Loading your items…</p></div>}
      {state.items !== null && state.items.length === 0 && <EmptyState><h2>No items yet</h2><p>Create an item to get started.</p><button onClick={onCreate}>Create item</button></EmptyState>}
      {state.items !== null && state.items.length > 0 && <ul>{state.items.map(item => <li key={item.id}>{item.title}</li>)}</ul>}
    </div>
  </section>;
}
// Supply a stable load callback. This adapter owns transport and preserves
// the previous snapshot through refresh and recoverable failure.
